(6245988, 923625, 15711, '<td valign="top">Stunning.  Terrific leading lines.  The sun isn''t overly "hot" yet it glows and reflects on the wet snow.</td>', 'Stunning.  Terrific leading lines.  The sun isn''t overly "hot" yet it glows and reflects on the wet snow.', '2010-12-06 09:15:09.000000', NULL, 1),
(6245990, 923701, 15711, '<td valign="top">If I remember, this is a memorial in Washington DC?  I like the effect, but can''t see how you did it using the rules.  I hope you did cause it''s really cool.</td>', 'If I remember, this is a memorial in Washington DC?  I like the effect, but can''t see how you did it using the rules.  I hope you did cause it''s really cool.', '2010-12-06 09:16:22.000000', NULL, 1),
(6245993, 923514, 15711, '<td valign="top">What really makes this for me is the reflection or the light coming through those windows at the top of the barn loft.  Really beautiful.  I''d love to see it HUGE on a wall. :)</td>', 'What really makes this for me is the reflection or the light coming through those windows at the top of the barn loft.  Really beautiful.  I''d love to see it HUGE on a wall. :)', '2010-12-06 09:17:06.000000', NULL, 1),
