(6246127, 923953, 96751, '<td valign="top">Marvelous.  I''d have opted for a tighter, square crop, with the sand portion the same size as the sky.</td>', 'Marvelous.  I''d have opted for a tighter, square crop, with the sand portion the same size as the sky.', '2010-12-06 11:52:05.000000', NULL, 1),
(6246131, 923406, 96751, '<td valign="top">Strange and incongruous.  Love the colors, the sense of isolation from the mainstream, which can be seen in the distance.  But that ghosting...</td>', 'Strange and incongruous.  Love the colors, the sense of isolation from the mainstream, which can be seen in the distance.  But that ghosting...', '2010-12-06 11:53:10.000000', NULL, 1),
