(6246552, 923591, 99263, '<td valign="top">Very nice the way the jetty and chair are silhouetted against the rising mist from the waters surface and then the dark background with treeline rising up behind it. Lovely tones too.</td>', 'Very nice the way the jetty and chair are silhouetted against the rising mist from the waters surface and then the dark background with treeline rising up behind it. Lovely tones too.', '2010-12-06 19:19:51.000000', NULL, 1),
(6246554, 923897, 18197, '<td valign="top">If I were to describe this photo to someone who hadn''t seen it, the word horizon probably wouldn''t be in my description. Hard to imagine the horizon is the dominant element in the photo.</td>', 'If I were to describe this photo to someone who hadn''t seen it, the word horizon probably wouldn''t be in my description. Hard to imagine the horizon is the dominant element in the photo.', '2010-12-06 19:20:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6246555, 923734, 99263, '<td valign="top">Beautiful clarity and light.</td>', 'Beautiful clarity and light.', '2010-12-06 19:20:12.000000', NULL, 1),
(6246556, 923716, 18197, '<td valign="top">While there is a horizon in the photo it''s  hard to imagine the horizon is the dominant element in the photo.</td>', 'While there is a horizon in the photo it''s  hard to imagine the horizon is the dominant element in the photo.', '2010-12-06 19:20:51.000000', NULL, 1),
(6246557, 923476, 18197, '<td valign="top">I like this photo a lot, and there''s a horizon but it''s hard to imagine the horizon is the dominant element in the photo.</td>', 'I like this photo a lot, and there''s a horizon but it''s hard to imagine the horizon is the dominant element in the photo.', '2010-12-06 19:21:44.000000', NULL, 1),
(6246558, 923857, 23484, '<td valign="top">Love the off center composition.</td>', 'Love the off center composition.', '2010-12-06 19:21:54.000000', NULL, 1),
(6246559, 923894, 23484, '<td valign="top">Sometimes simplicity is the best. Nice job.</td>', 'Sometimes simplicity is the best. Nice job.', '2010-12-06 19:22:13.000000', NULL, 1),
(6246560, 923703, 23484, '<td valign="top">Gorgeous colors in the sky. Nice job.</td>', 'Gorgeous colors in the sky. Nice job.', '2010-12-06 19:22:28.000000', NULL, 1),
(6246561, 923958, 18197, '<td valign="top">It feels to me that the tree with it''s ornaments is the dominant element here and hard to imagine the horizon is the dominant element in the photo.</td>', 'It feels to me that the tree with it''s ornaments is the dominant element here and hard to imagine the horizon is the dominant element in the photo.', '2010-12-06 19:23:06.000000', NULL, 1),
(6246562, 923559, 23484, '<td valign="top">This is so freakin cool. How did you do this? 10</td>', 'This is so freakin cool. How did you do this? 10', '2010-12-06 19:23:16.000000', NULL, 1),
(6246563, 923706, 23484, '<td valign="top">Very neat image. Love the oof.</td>', 'Very neat image. Love the oof.', '2010-12-06 19:23:44.000000', NULL, 1),
(6246564, 923719, 18197, '<td valign="top">Wonderful photo that nails the challenge theme perfectly. Well done - my only 10 in this challenge.</td>', 'Wonderful photo that nails the challenge theme perfectly. Well done - my only 10 in this challenge.', '2010-12-06 19:24:00.000000', NULL, 1),
(6246565, 923634, 23484, '<td valign="top">Great image. The color tone is  perfect.</td>', 'Great image. The color tone is  perfect.', '2010-12-06 19:24:15.000000', NULL, 1),
(6246567, 923807, 23484, '<td valign="top">Very nice use of negative space.</td>', 'Very nice use of negative space.', '2010-12-06 19:24:40.000000', NULL, 1),
(6246569, 923634, 18197, '<td valign="top">Very few photos in the challenge meet the challenge theme very well. This is a superb exception. Super photo. Thanks for showing us this winter horizon.</td>', 'Very few photos in the challenge meet the challenge theme very well. This is a superb exception. Super photo. Thanks for showing us this winter horizon.', '2010-12-06 19:25:02.000000', NULL, 1),
(6246570, 923855, 23484, '<td valign="top">Very nice complementary colors. Gorgeous.</td>', 'Very nice complementary colors. Gorgeous.', '2010-12-06 19:25:29.000000', NULL, 1),
(6246571, 923812, 23484, '<td valign="top">The leading lines are very nice. It really draws the eye in.</td>', 'The leading lines are very nice. It really draws the eye in.', '2010-12-06 19:25:58.000000', NULL, 1),
(6246572, 923666, 23484, '<td valign="top">Very Ansel Adams looking. Great B&amp;W Conversion.</td>', 'Very Ansel Adams looking. Great B&W Conversion.', '2010-12-06 19:27:04.000000', NULL, 1),
(6246574, 923866, 18197, '<td valign="top">Yep, the horizon is the dominant theme here and I find the photo pleasing. You may get some criticism about splitting the frame horizontally. And in general it''s a rule to break with care. In THIS case i feel it works perfectly because of the similarity of the snow in the foreground and the featureless sky. Well done.</td>', 'Yep, the horizon is the dominant theme here and I find the photo pleasing. You may get some criticism about splitting the frame horizontally. And in general it''s a rule to break with care. In THIS case i feel it works perfectly because of the similarity of the snow in the foreground and the featureless sky. Well done.', '2010-12-06 19:27:33.000000', NULL, 1),
(6246576, 923322, 18197, '<td valign="top">This is an exceptional abstract which (unlike most entries) meets the challenge. What i thought was a dust speck may even be a buoy. Nope, I just moved the window on my screen and it''s on my screen - good grief. No worries - I love the photo.</td>', 'This is an exceptional abstract which (unlike most entries) meets the challenge. What i thought was a dust speck may even be a buoy. Nope, I just moved the window on my screen and it''s on my screen - good grief. No worries - I love the photo.', '2010-12-06 19:30:09.000000', NULL, 1),
(6246578, 923811, 18197, '<td valign="top">This is really terrific - a truly lovely abstract. To my mind it meets the challenge. And the colors and textures are terrific. Well done! I fear for your score because DPC voters don''t often reward abstracts but i gave it a GREAT score!</td>', 'This is really terrific - a truly lovely abstract. To my mind it meets the challenge. And the colors and textures are terrific. Well done! I fear for your score because DPC voters don''t often reward abstracts but i gave it a GREAT score!', '2010-12-06 19:31:51.000000', NULL, 1),
(6246580, 923566, 18197, '<td valign="top">Unusual take on the challenge which I appreciate and like a lot. Thanks for your creative take on this. Great work!</td>', 'Unusual take on the challenge which I appreciate and like a lot. Thanks for your creative take on this. Great work!', '2010-12-06 19:32:47.000000', NULL, 1),
(6246605, 923725, 99263, '<td valign="top">Dramatic looking image. Lovely with the city nestled below the mountains like that. The focus looks a bit blurry though.</td>', 'Dramatic looking image. Lovely with the city nestled below the mountains like that. The focus looks a bit blurry though.', '2010-12-06 19:46:46.000000', NULL, 1),
(6246606, 923701, 99263, '<td valign="top">Well done and certainly creative. Nice effect with the reflections. Effective and dramatic use of back lighting too. Very unusual entry and quite different. <br/>Looking forward to reading your photographers comments after the voting is over. 7</td>', 'Well done and certainly creative. Nice effect with the reflections. Effective and dramatic use of back lighting too. Very unusual entry and quite different. Looking forward to reading your photographers comments after the voting is over. 7', '2010-12-06 19:49:50.000000', NULL, 1),
(6246607, 923867, 99263, '<td valign="top">Cool and icy view. The 2 figures with dog are a nice addition in the composition.</td>', 'Cool and icy view. The 2 figures with dog are a nice addition in the composition.', '2010-12-06 19:50:50.000000', NULL, 1),
(6246608, 923746, 99263, '<td valign="top">Very nice misty blue tones. The 2 figures with the dog in the mist add a nice touch and a point of interest. Pity about the 2 pieces of wood in the foreground. They distract a bit imo. 7</td>', 'Very nice misty blue tones. The 2 figures with the dog in the mist add a nice touch and a point of interest. Pity about the 2 pieces of wood in the foreground. They distract a bit imo. 7', '2010-12-06 19:53:18.000000', NULL, 1),
(6246609, 923406, 99263, '<td valign="top">Certainly different and colorful. I hope you will post a bit of a background to this image in the photographers comments. I look forward to reading them.</td>', 'Certainly different and colorful. I hope you will post a bit of a background to this image in the photographers comments. I look forward to reading them.', '2010-12-06 19:54:43.000000', NULL, 1),
(6246611, 923649, 99263, '<td valign="top">Very dramatic and brooding image. I love the texture of the hay. Almost looks like a wolves fur. 7</td>', 'Very dramatic and brooding image. I love the texture of the hay. Almost looks like a wolves fur. 7', '2010-12-06 19:56:33.000000', NULL, 1),
(6246612, 923322, 99263, '<td valign="top">Smooth and tranquil. Nice.</td>', 'Smooth and tranquil. Nice.', '2010-12-06 19:56:59.000000', NULL, 1),
(6246615, 923421, 99263, '<td valign="top">Nice composition. Centered horizon line works well here. Not sure if I like the grainy sky though.</td>', 'Nice composition. Centered horizon line works well here. Not sure if I like the grainy sky though.', '2010-12-06 19:58:16.000000', NULL, 1),
(6246620, 923754, 99263, '<td valign="top">It''s a very stunning image this and the processing is wonderful. Lovely textured feel to it also. 8</td>', 'It''s a very stunning image this and the processing is wonderful. Lovely textured feel to it also. 8', '2010-12-06 20:00:46.000000', NULL, 1),
(6246623, 923897, 99263, '<td valign="top">Lovely capture. Wild and free.</td>', 'Lovely capture. Wild and free.', '2010-12-06 20:01:16.000000', NULL, 1),
(6246625, 923938, 99263, '<td valign="top">Wonderful tones and light, nice dreaminess.  7</td>', 'Wonderful tones and light, nice dreaminess.  7', '2010-12-06 20:02:30.000000', NULL, 1),
(6246628, 923703, 99263, '<td valign="top">A visual pleasure. Love that swirling sky and the play of golden light within the clouds. Tolkinish landscape below. 7</td>', 'A visual pleasure. Love that swirling sky and the play of golden light within the clouds. Tolkinish landscape below. 7', '2010-12-06 20:04:07.000000', NULL, 1),
(6246631, 923625, 99263, '<td valign="top">Lovely winter scene with beautiful silvery light.</td>', 'Lovely winter scene with beautiful silvery light.', '2010-12-06 20:05:09.000000', NULL, 1),
(6246634, 923957, 99263, '<td valign="top">Nicely silhouetted composition but I would have liked the trees to be in focus and sharply defined. As it is now it looks a bit fuzzy.</td>', 'Nicely silhouetted composition but I would have liked the trees to be in focus and sharply defined. As it is now it looks a bit fuzzy.', '2010-12-06 20:06:36.000000', NULL, 1),
(6246637, 923715, 99263, '<td valign="top">Nice wintry view with lots of depth.</td>', 'Nice wintry view with lots of depth.', '2010-12-06 20:07:17.000000', NULL, 1),
(6246642, 923476, 99263, '<td valign="top">Lovely view over the rooftops. Nice clarity and detail and I like the way the sun lights up the buildings on the left.</td>', 'Lovely view over the rooftops. Nice clarity and detail and I like the way the sun lights up the buildings on the left.', '2010-12-06 20:08:47.000000', NULL, 1),
(6246644, 923728, 99263, '<td valign="top">Stunning wintry lake scene. Lovely reflections. 7</td>', 'Stunning wintry lake scene. Lovely reflections. 7', '2010-12-06 20:09:31.000000', NULL, 1),
(6246649, 923335, 99263, '<td valign="top">Dramatic silhouettes against a fiery sky. That sun actually burns onto my retina so real and bright. 7</td>', 'Dramatic silhouettes against a fiery sky. That sun actually burns onto my retina so real and bright. 7', '2010-12-06 20:12:31.000000', NULL, 1),
(6246651, 923904, 99263, '<td valign="top">Beautiful dark shadows in the rocks. Very nice seascape. 7</td>', 'Beautiful dark shadows in the rocks. Very nice seascape. 7', '2010-12-06 20:13:35.000000', NULL, 1),
(6246652, 923716, 99263, '<td valign="top">Nice perspective and processing.</td>', 'Nice perspective and processing.', '2010-12-06 20:14:06.000000', NULL, 1),
(6246654, 923556, 99263, '<td valign="top">Striking composition, excellent exposure. 8</td>', 'Striking composition, excellent exposure. 8', '2010-12-06 20:15:19.000000', NULL, 1),
(6246656, 923568, 99263, '<td valign="top">Very dramatic image with the statue of liberty and those harbor cranes in the distance across the black waters. 7</td>', 'Very dramatic image with the statue of liberty and those harbor cranes in the distance across the black waters. 7', '2010-12-06 20:19:11.000000', NULL, 1),
(6246657, 923398, 99263, '<td valign="top">Behold indeed. Striking and appealing. Lovely because of it''s simplicity, smooth tones and deep rich colors. Wonderful composition too and excellent exposure. I like the way the light in the lantern has been captured especially. 8</td>', 'Behold indeed. Striking and appealing. Lovely because of it''s simplicity, smooth tones and deep rich colors. Wonderful composition too and excellent exposure. I like the way the light in the lantern has been captured especially. 8', '2010-12-06 20:22:20.000000', NULL, 1),
(6246658, 923624, 99263, '<td valign="top">Lovely misty morning freshness in this image. Nice smooth tones and colors. 7</td>', 'Lovely misty morning freshness in this image. Nice smooth tones and colors. 7', '2010-12-06 20:23:00.000000', NULL, 1),
(6246659, 923714, 99263, '<td valign="top">There is certainly an air of mystery being exuded by this image. Like what''s over there far in the distant mist? Lost islands or ghostly ships. It looks like quite a barren inhospitable shore from where you took the photo.</td>', 'There is certainly an air of mystery being exuded by this image. Like what''s over there far in the distant mist? Lost islands or ghostly ships. It looks like quite a barren inhospitable shore from where you took the photo.', '2010-12-06 20:26:03.000000', NULL, 1),
(6246660, 923621, 99263, '<td valign="top">Great composition, lovely deep azure blues.</td>', 'Great composition, lovely deep azure blues.', '2010-12-06 20:26:37.000000', NULL, 1),
(6246699, 923193, 30861, '<td valign="top">I love the picture but for the life of me I can''t find much challenge relevance in it, sorry.</td>', 'I love the picture but for the life of me I can''t find much challenge relevance in it, sorry.', '2010-12-06 21:00:08.000000', NULL, 1),
(6246747, 923932, 112739, '<td valign="top">I think the horizon should be at least noticeable in the image since it supposed to be a dominant part of the image.</td>', 'I think the horizon should be at least noticeable in the image since it supposed to be a dominant part of the image.', '2010-12-06 21:40:26.000000', NULL, 1),
(6246752, 923649, 112739, '<td valign="top">The Blue for me. Love it!</td>', 'The Blue for me. Love it!', '2010-12-06 21:44:53.000000', NULL, 1),
(6246759, 923857, 112739, '<td valign="top">verrry nice. Just like I am standing there.</td>', 'verrry nice. Just like I am standing there.', '2010-12-06 21:47:34.000000', NULL, 1),
(6246762, 923702, 112739, '<td valign="top">Wow, what a strong sky!</td>', 'Wow, what a strong sky!', '2010-12-06 21:48:29.000000', NULL, 1),
(6246764, 923666, 112739, '<td valign="top">I like everything with the exception of the halo around the tree. Wonderful shot.</td>', 'I like everything with the exception of the halo around the tree. Wonderful shot.', '2010-12-06 21:49:29.000000', NULL, 1),
(6246768, 923193, 112739, '<td valign="top">posthumos winner in my book, love the feel. Although I am not sure about where the horizon line is. Interpretation.</td>', 'posthumos winner in my book, love the feel. Although I am not sure about where the horizon line is. Interpretation.', '2010-12-06 21:51:16.000000', NULL, 1),
(6246771, 923559, 112739, '<td valign="top">I cannot say why this image appeals to me, but it does.</td>', 'I cannot say why this image appeals to me, but it does.', '2010-12-06 21:52:37.000000', NULL, 1),
(6246773, 923719, 112739, '<td valign="top">Even though the image is small, I can image this being on my wall in a larger scale. Love it.</td>', 'Even though the image is small, I can image this being on my wall in a larger scale. Love it.', '2010-12-06 21:54:01.000000', NULL, 1),
