(6246849, 923701, 80904, '<td valign="top">oh man I so want to give this a 10. Its a spectacular image. I have reservations though since its not a horizon shot for me. Clearly the subject are the statues. And the horizon is behind them. So I give it an 8</td>', 'oh man I so want to give this a 10. Its a spectacular image. I have reservations though since its not a horizon shot for me. Clearly the subject are the statues. And the horizon is behind them. So I give it an 8', '2010-12-06 23:12:10.000000', NULL, 1),
(6246980, 923807, 93565, '<td valign="top">Very nice BW processing. I like this quite a bit. Nice mix of sky and Earth, and interesting curvature of the hill.</td>', 'Very nice BW processing. I like this quite a bit. Nice mix of sky and Earth, and interesting curvature of the hill.', '2010-12-07 04:36:13.000000', NULL, 1),
(6246990, 923855, 93565, '<td valign="top">Interesting texture to the sky. A nice, different look from many of the others. The more mellow colors are appreciated too. Good shot.</td>', 'Interesting texture to the sky. A nice, different look from many of the others. The more mellow colors are appreciated too. Good shot.', '2010-12-07 05:17:38.000000', NULL, 1),
(6247005, 923812, 108069, '<td valign="top">Great leading line that fades off into the horizon. Nice, gloomy scene. My kind of stuff. Well done.</td>', 'Great leading line that fades off into the horizon. Nice, gloomy scene. My kind of stuff. Well done.', '2010-12-07 06:12:39.000000', NULL, 1),
(6247007, 923857, 99263, '<td valign="top">Nice composition but apart from the section on the left lit up by the sun I find the colors and general impression of the rest of the image a bit dull and flat. Lifeless so to speak. It needs some luminance imo.</td>', 'Nice composition but apart from the section on the left lit up by the sun I find the colors and general impression of the rest of the image a bit dull and flat. Lifeless so to speak. It needs some luminance imo.', '2010-12-07 06:13:59.000000', NULL, 1),
(6247008, 923886, 108069, '<td valign="top">Beautiful photo. Excellent use of the peak in the foregrouns to break up the distant horizon. Nice tones and colors, some obvious work done to display a greater range of exposure, but very well processed to not be overdone. Just right. Excellent shot.</td>', 'Beautiful photo. Excellent use of the peak in the foregrouns to break up the distant horizon. Nice tones and colors, some obvious work done to display a greater range of exposure, but very well processed to not be overdone. Just right. Excellent shot.', '2010-12-07 06:14:29.000000', NULL, 1),
(6247010, 923482, 99263, '<td valign="top">A bit too obscure/d.</td>', 'A bit too obscure/d.', '2010-12-07 06:15:13.000000', NULL, 1),
(6247013, 923193, 99263, '<td valign="top">Whilst a pleasing image I find it a bit too abstract and obscure to fit the bill for this challenge theme.</td>', 'Whilst a pleasing image I find it a bit too abstract and obscure to fit the bill for this challenge theme.', '2010-12-07 06:19:17.000000', NULL, 1),
(6247014, 923250, 99263, '<td valign="top">Lovely textures and rich dark tones and color. Whilst a pleasing image I find it a bit too abstract and obscure to fit the bill for this challenge theme.</td>', 'Lovely textures and rich dark tones and color. Whilst a pleasing image I find it a bit too abstract and obscure to fit the bill for this challenge theme.', '2010-12-07 06:20:16.000000', NULL, 1),
(6247015, 923753, 99263, '<td valign="top">A little too dark and obscure to fit the bill for this challenge theme imo.</td>', 'A little too dark and obscure to fit the bill for this challenge theme imo.', '2010-12-07 06:21:30.000000', NULL, 1),
(6247016, 923559, 99263, '<td valign="top">Whilst a pleasing image with nice textures and colors I find it a bit too abstract and obscure to fit the bill for this challenge theme.</td>', 'Whilst a pleasing image with nice textures and colors I find it a bit too abstract and obscure to fit the bill for this challenge theme.', '2010-12-07 06:22:13.000000', NULL, 1),
(6247022, 923846, 99263, '<td valign="top">Just a little dull and lifeless looking. Also a bit obscurish.</td>', 'Just a little dull and lifeless looking. Also a bit obscurish.', '2010-12-07 06:27:35.000000', NULL, 1),
(6247024, 923958, 99263, '<td valign="top">Pretty unusual. I notice there''s another homeless tree in the challenge. What''s the homeless tree all about?</td>', 'Pretty unusual. I notice there''s another homeless tree in the challenge. What''s the homeless tree all about?', '2010-12-07 06:29:35.000000', NULL, 1),
(6247028, 923575, 99263, '<td valign="top">Lovely vista. Nice b&amp;w conversion.</td>', 'Lovely vista. Nice b&w conversion.', '2010-12-07 06:32:31.000000', NULL, 1),
(6247035, 923758, 108069, '<td valign="top">The blown out sky to the right and the crooked horizon are slightly annoying, but it''s a nice scene and a great example of a horizon.</td>', 'The blown out sky to the right and the crooked horizon are slightly annoying, but it''s a nice scene and a great example of a horizon.', '2010-12-07 06:44:23.000000', NULL, 1),
(6247039, 923890, 108069, '<td valign="top">Awesome shot. A story, great exposure, excellent composition, and a prominent horizon; and beautiful. Excellent.</td>', 'Awesome shot. A story, great exposure, excellent composition, and a prominent horizon; and beautiful. Excellent.', '2010-12-07 06:46:03.000000', NULL, 1),
(6247054, 923622, 23484, '<td valign="top">Very nice image. The birds really add a lot.</td>', 'Very nice image. The birds really add a lot.', '2010-12-07 07:09:11.000000', NULL, 1),
(6247055, 923716, 23484, '<td valign="top">Very neat composition. It all fits together so nicely.</td>', 'Very neat composition. It all fits together so nicely.', '2010-12-07 07:09:44.000000', NULL, 1),
(6247057, 923654, 23484, '<td valign="top">Now that''s a scarey thought.</td>', 'Now that''s a scarey thought.', '2010-12-07 07:10:20.000000', NULL, 1),
(6247058, 923193, 23484, '<td valign="top">Blowing in the wind. Very nice image.</td>', 'Blowing in the wind. Very nice image.', '2010-12-07 07:11:07.000000', NULL, 1),
