(6249379, 923654, 69034, '<td valign="top">This shot appeals to me for some reason, but the distinction between the earth and sky is too diffuse for me to focus on the horizon line.</td>', 'This shot appeals to me for some reason, but the distinction between the earth and sky is too diffuse for me to focus on the horizon line.', '2010-12-08 19:20:10.000000', NULL, 1),
(6249380, 923716, 69034, '<td valign="top">This is one of the few shots with a major obstacle in the foreground that worked for me.  I think the object in the distance forces my eyes away from the fore. . .nice.</td>', 'This is one of the few shots with a major obstacle in the foreground that worked for me.  I think the object in the distance forces my eyes away from the fore. . .nice.', '2010-12-08 19:22:16.000000', NULL, 1),
(6249383, 923806, 69034, '<td valign="top">Exposure was an awesome idea on this challenge.  Upped the focus on the sky which might have been skewed by the rocks in the fore. . .Nice.</td>', 'Exposure was an awesome idea on this challenge.  Upped the focus on the sky which might have been skewed by the rocks in the fore. . .Nice.', '2010-12-08 19:25:20.000000', NULL, 1),
(6249384, 923753, 114285, '<td valign="top">Cool shot.</td>', 'Cool shot.', '2010-12-08 19:27:36.000000', NULL, 1),
(6249385, 923894, 114285, '<td valign="top">Nice is this Ursula ?</td>', 'Nice is this Ursula ?', '2010-12-08 19:28:09.000000', NULL, 1),
(6249387, 923752, 114285, '<td valign="top">Love that beam of sunshine on the river, great shot.</td>', 'Love that beam of sunshine on the river, great shot.', '2010-12-08 19:28:49.000000', NULL, 1),
(6249438, 923514, 79184, '<td valign="top">Very nice! Great colours.</td>', 'Very nice! Great colours.', '2010-12-08 20:18:48.000000', NULL, 1),
(6249585, 923938, 116574, '<td valign="top">Where''s the horizon?  See something in the bottom of the picture but not enough difference for my tastes.</td>', 'Where''s the horizon?  See something in the bottom of the picture but not enough difference for my tastes.', '2010-12-08 23:02:52.000000', NULL, 1),
(6249760, 923846, 108069, '<td valign="top">Awesome image. Excellent.</td>', 'Awesome image. Excellent.', '2010-12-09 08:40:21.000000', NULL, 1),
(6249761, 923559, 108069, '<td valign="top">Whatever you say Mr. van Gogh. Seriously cool photo here. I really like the burnt edges; gives it a frame that helps it out yet isn''t stodgy or confining.<br/> <br/>Please tell me how you did this so I can play also. Excellent.</td>', 'Whatever you say Mr. van Gogh. Seriously cool photo here. I really like the burnt edges; gives it a frame that helps it out yet isn''t stodgy or confining. Please tell me how you did this so I can play also. Excellent.', '2010-12-09 08:43:34.000000', NULL, 1),
(6249773, 923649, 108069, '<td valign="top">This is fantastic. I had a similar idea with a semi-similar scene and I at least know I was correct with my vision, as this is superb, but my execution certainly didn''t match this. Glad I decided to enter some other lousy photo, as this would have just put a spotlight on the difference in quality.<br/> <br/>The way the grass fades to black is wonderful, the detail is crisp yet soft enough to give it a blanket feel. The contrast between blades is great. Clouds as well. Overall great composition. One of my favorites in a field of top-quality entries. Well done.<br/> <br/>Came back to fave this. I might paste in on my glasses.</td>', 'This is fantastic. I had a similar idea with a semi-similar scene and I at least know I was correct with my vision, as this is superb, but my execution certainly didn''t match this. Glad I decided to enter some other lousy photo, as this would have just put a spotlight on the difference in quality. The way the grass fades to black is wonderful, the detail is crisp yet soft enough to give it a blanket feel. The contrast between blades is great. Clouds as well. Overall great composition. One of my favorites in a field of top-quality entries. Well done. Came back to fave this. I might paste in on my glasses.', '2010-12-09 08:55:18.000000', NULL, 1),
(6249780, 923568, 108069, '<td valign="top">Powerful. Wonderful image.</td>', 'Powerful. Wonderful image.', '2010-12-09 08:57:47.000000', NULL, 1),
(6249784, 923622, 108069, '<td valign="top">I like how there''s a visual line that leads down with the birds and then up with the clouds. As if nature is creating its own horizon to compete with your seascape horizon. Great photo.</td>', 'I like how there''s a visual line that leads down with the birds and then up with the clouds. As if nature is creating its own horizon to compete with your seascape horizon. Great photo.', '2010-12-09 08:59:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6249933, 923592, 113156, '<td valign="top">the clouds really define the horizon line, very pleasant shot makes me want to be there.</td>', 'the clouds really define the horizon line, very pleasant shot makes me want to be there.', '2010-12-09 13:35:50.000000', NULL, 1),
(6249935, 923857, 113156, '<td valign="top">very effective, love the fact that there is not much to it and that the track leads us to the horizon.</td>', 'very effective, love the fact that there is not much to it and that the track leads us to the horizon.', '2010-12-09 13:38:47.000000', NULL, 1),
(6249941, 923894, 113156, '<td valign="top">Fabulous, would like to see this on my wall, very soothing pic.</td>', 'Fabulous, would like to see this on my wall, very soothing pic.', '2010-12-09 13:43:37.000000', NULL, 1),
(6249948, 923649, 113156, '<td valign="top">Thought it was a cows back until i spotted the pieces of wood, overall i really like it, its different and fits the challenge perfectly a 9.</td>', 'Thought it was a cows back until i spotted the pieces of wood, overall i really like it, its different and fits the challenge perfectly a 9.', '2010-12-09 13:47:20.000000', NULL, 1),
(6250060, 923688, 108069, '<td valign="top">Awesome perspective. Excellent photo.</td>', 'Awesome perspective. Excellent photo.', '2010-12-09 17:23:16.000000', NULL, 1),
(6250066, 923666, 108069, '<td valign="top">What a scene. Reminds me of the San Juans. Excellent composition, unreal depth. Just excellent.</td>', 'What a scene. Reminds me of the San Juans. Excellent composition, unreal depth. Just excellent.', '2010-12-09 17:39:14.000000', NULL, 1),
(6250068, 923959, 108069, '<td valign="top">Nice tones. Maybe going for an old-timey photo, and it''s working, but I still want to see it big, because it''s a great shot. Big and grainy would be even better.</td>', 'Nice tones. Maybe going for an old-timey photo, and it''s working, but I still want to see it big, because it''s a great shot. Big and grainy would be even better.', '2010-12-09 17:45:36.000000', NULL, 1),
(6250071, 923958, 108069, '<td valign="top">Is it seriously duct-taped together? Interesting shot. I like the layers of foliage in the foreground before you get to the skyline.</td>', 'Is it seriously duct-taped together? Interesting shot. I like the layers of foliage in the foreground before you get to the skyline.', '2010-12-09 17:47:31.000000', NULL, 1),
(6250074, 923945, 108069, '<td valign="top">A lot of elements in balance here. Lines everywhere and that''s nice. Lovely capture of the setting sun with its rays downward. Nice exposure considering the harsh conditions. Well done.</td>', 'A lot of elements in balance here. Lines everywhere and that''s nice. Lovely capture of the setting sun with its rays downward. Nice exposure considering the harsh conditions. Well done.', '2010-12-09 17:48:58.000000', NULL, 1),
(6250077, 923749, 108069, '<td valign="top">Beautiful photo. This has to be somewhere in Asia. I like guessing to see just how wrong I can be. Well balanced, nice skyscape with lovely colors and tones. Nice work.</td>', 'Beautiful photo. This has to be somewhere in Asia. I like guessing to see just how wrong I can be. Well balanced, nice skyscape with lovely colors and tones. Nice work.', '2010-12-09 17:50:12.000000', NULL, 1),
(6250100, 923250, 108069, '<td valign="top">As though it were airbrushed. I love the contrast and tones.</td>', 'As though it were airbrushed. I love the contrast and tones.', '2010-12-09 18:44:38.000000', NULL, 1),
(6250114, 923714, 108069, '<td valign="top">Great how the sea fades into nothingness and then rebounds into the blue of the sky. The horizon line is certainly the striking bit of this image. I also like the understated, almost desaturated foreground, not distracting the eye from the sky and horizon. Nice one.</td>', 'Great how the sea fades into nothingness and then rebounds into the blue of the sky. The horizon line is certainly the striking bit of this image. I also like the understated, almost desaturated foreground, not distracting the eye from the sky and horizon. Nice one.', '2010-12-09 19:03:18.000000', NULL, 1),
(6250117, 923193, 108069, '<td valign="top">What a great image. Contrast, the set white points, the steel-brushed white, the flutter. Great.</td>', 'What a great image. Contrast, the set white points, the steel-brushed white, the flutter. Great.', '2010-12-09 19:05:59.000000', NULL, 1),
(6250120, 923915, 108069, '<td valign="top">Rarely is a photo more crisp with such lovely colors. Exposure range is outstanding, yet no softening due to HDR. Clouds are popping, sun offset. Amazing photo.</td>', 'Rarely is a photo more crisp with such lovely colors. Exposure range is outstanding, yet no softening due to HDR. Clouds are popping, sun offset. Amazing photo.', '2010-12-09 19:07:39.000000', NULL, 1),
(6250122, 923845, 108069, '<td valign="top">Lovely scene. Very, very nice. I would have gone darker, but I like them dark. Well spotted.</td>', 'Lovely scene. Very, very nice. I would have gone darker, but I like them dark. Well spotted.', '2010-12-09 19:08:58.000000', NULL, 1),
(6250125, 923932, 108069, '<td valign="top">Wow. Reminds me of Greece. Great perspective. The horizon line is virtually undetectable here, but that adds to the mystery of this truly interesting scene. Well done.</td>', 'Wow. Reminds me of Greece. Great perspective. The horizon line is virtually undetectable here, but that adds to the mystery of this truly interesting scene. Well done.', '2010-12-09 19:10:31.000000', NULL, 1),
(6250128, 923709, 108069, '<td valign="top">Awesome. One of my three favorites. The tones are beautiful and the blur is masterful. Just right in every way.</td>', 'Awesome. One of my three favorites. The tones are beautiful and the blur is masterful. Just right in every way.', '2010-12-09 19:11:53.000000', NULL, 1),
(6250137, 923908, 108069, '<td valign="top">Wonderful. Is this a ferry to Bainbridge? Just a wild guess, but it looks like it. I''d say PNW regardless. Portrait layout is ideal for this as there are so many layers to the sky and horizon and sound/water. I particularly like the midnight blue at the top in contrast with the orangish tint in the horizon. Complimentary colors DO work, even separated by an extremely interesting cloud layer. Excellent photo.</td>', 'Wonderful. Is this a ferry to Bainbridge? Just a wild guess, but it looks like it. I''d say PNW regardless. Portrait layout is ideal for this as there are so many layers to the sky and horizon and sound/water. I particularly like the midnight blue at the top in contrast with the orangish tint in the horizon. Complimentary colors DO work, even separated by an extremely interesting cloud layer. Excellent photo.', '2010-12-09 19:18:58.000000', NULL, 1),
(6250138, 923322, 108069, '<td valign="top">Simply elegant. What a shot. Perfect title. Easily one of my favorites. Outstanding.<br/> <br/>Back to add it as a favorite.</td>', 'Simply elegant. What a shot. Perfect title. Easily one of my favorites. Outstanding. Back to add it as a favorite.', '2010-12-09 19:20:21.000000', NULL, 1),
(6250145, 923918, 23484, '<td valign="top">The colors are incredible. Almost pastel.</td>', 'The colors are incredible. Almost pastel.', '2010-12-09 19:30:58.000000', NULL, 1),
(6250148, 923250, 23484, '<td valign="top">Absolutely beautiful image. The granular effect of your effectuality is effectively effective.  I couldn''t help myself. Nice job.</td>', 'Absolutely beautiful image. The granular effect of your effectuality is effectively effective.  I couldn''t help myself. Nice job.', '2010-12-09 19:33:40.000000', NULL, 1),
(6250150, 923649, 23484, '<td valign="top">The windblown look of the grass really draws the eye in.</td>', 'The windblown look of the grass really draws the eye in.', '2010-12-09 19:34:39.000000', NULL, 1),
(6250221, 923957, 51747, '<td valign="top">Love the colors here. As defined in the challenge description, there isn''t a lot of horizon visible. Nice shot anyway.</td>', 'Love the colors here. As defined in the challenge description, there isn''t a lot of horizon visible. Nice shot anyway.', '2010-12-09 21:42:30.000000', NULL, 1),
(6250222, 923854, 51747, '<td valign="top">Some haloing on the horizon line is not a benefit to your score.</td>', 'Some haloing on the horizon line is not a benefit to your score.', '2010-12-09 21:44:09.000000', NULL, 1),
(6250223, 923649, 51747, '<td valign="top">A little tight for a horizon shot. But the flow in the hay is really sweet.</td>', 'A little tight for a horizon shot. But the flow in the hay is really sweet.', '2010-12-09 21:45:45.000000', NULL, 1),
