(6250256, 923504, 109227, '<td valign="top">One of my favs of the challenge; the slight movement of the person adds to the image.</td>', 'One of my favs of the challenge; the slight movement of the person adds to the image.', '2010-12-09 22:52:10.000000', NULL, 1),
