(6250260, 923483, 109227, '<td valign="top">This image really spoke to me; the contrasting colors and the rolling field make a lovely image.  Nice job.</td>', 'This image really spoke to me; the contrasting colors and the rolling field make a lovely image.  Nice job.', '2010-12-09 22:53:38.000000', NULL, 1),
