(6250263, 923709, 109227, '<td valign="top">I like the soft affect here; just enough to see beyond but still and quite.  Nicely done.</td>', 'I like the soft affect here; just enough to see beyond but still and quite.  Nicely done.', '2010-12-09 22:54:38.000000', NULL, 1),
(6250266, 923945, 109227, '<td valign="top">Lovely.  Just enough light to see a few details; soft and quite.  Nice processing/</td>', 'Lovely.  Just enough light to see a few details; soft and quite.  Nice processing/', '2010-12-09 22:55:56.000000', NULL, 1),
(6250341, 923938, 54645, '<td valign="top">Ha! Good stuff.</td>', 'Ha! Good stuff.', '2010-12-10 00:56:21.000000', NULL, 1),
