(6252146, 923922, 65035, '<td valign="top">That water looks icy and they look a bit reluctant all lined up like that, such pretty colours</td>', 'That water looks icy and they look a bit reluctant all lined up like that, such pretty colours', '2010-12-12 22:22:24.000000', NULL, 1),
(6252147, 923918, 65035, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2010-12-12 22:22:50.000000', NULL, 1),
(6252157, 923559, 53814, '<td valign="top">my favorite of this challenge. I love the sheepish looking clouds.</td>', 'my favorite of this challenge. I love the sheepish looking clouds.', '2010-12-12 22:45:01.000000', NULL, 1),
(6252172, 923406, 90474, '<td valign="top">The composition pulls the eye away from the horizon and draws attention to the sign.  A few steps back and to the right might have improved the shot.  7 for focus, DOF and color.</td>', 'The composition pulls the eye away from the horizon and draws attention to the sign.  A few steps back and to the right might have improved the shot.  7 for focus, DOF and color.', '2010-12-12 22:59:13.000000', NULL, 1),
(6252175, 923193, 76335, '<td valign="top">The blackest and the whitest of all. Insanely good.</td>', 'The blackest and the whitest of all. Insanely good.', '2010-12-12 23:03:14.000000', NULL, 1),
(6252177, 923702, 76335, '<td valign="top">The horizon gets lost amidst the sky and village competing with each other. It''s like trying to draw attention to the net during a heated tennis match. <br/> <br/>But who really cares about challenge themes anyway. This is astounding.</td>', 'The horizon gets lost amidst the sky and village competing with each other. It''s like trying to draw attention to the net during a heated tennis match.  But who really cares about challenge themes anyway. This is astounding.', '2010-12-12 23:06:35.000000', NULL, 1),
(6252183, 923930, 76335, '<td valign="top">A beautiful palette of colors you used.</td>', 'A beautiful palette of colors you used.', '2010-12-12 23:07:06.000000', NULL, 1),
(6252186, 923854, 76335, '<td valign="top">Interesting how you aligned your horizon with the bottom of your frame. Gives it an interesting dynamic, draws attention to your message. There are plants and there are <i>plants</i>. Really good.</td>', 'Interesting how you aligned your horizon with the bottom of your frame. Gives it an interesting dynamic, draws attention to your message. There are plants and there are plants. Really good.', '2010-12-12 23:08:23.000000', NULL, 1),
(6252188, 923654, 76335, '<td valign="top">Yes, very apocalyptic. Well done.</td>', 'Yes, very apocalyptic. Well done.', '2010-12-12 23:08:51.000000', NULL, 1),
(6252191, 923753, 76335, '<td valign="top">They worship and dance and celebrate. Their god has come. I have a twisted imagination. Sorry. Seven.</td>', 'They worship and dance and celebrate. Their god has come. I have a twisted imagination. Sorry. Seven.', '2010-12-12 23:16:01.000000', NULL, 1),
(6252192, 923625, 76335, '<td valign="top">The sun tries hard to cut through the gloomy winter. Nicely done.</td>', 'The sun tries hard to cut through the gloomy winter. Nicely done.', '2010-12-12 23:16:40.000000', NULL, 1),
(6252193, 923421, 76335, '<td valign="top">Simply stated. Is that an island in the distance (far left)?</td>', 'Simply stated. Is that an island in the distance (far left)?', '2010-12-12 23:16:48.000000', NULL, 1),
(6252196, 923746, 76335, '<td valign="top">I do like the zigzag patterns in the ice.</td>', 'I do like the zigzag patterns in the ice.', '2010-12-12 23:16:57.000000', NULL, 1),
(6252197, 923556, 76335, '<td valign="top">Good radial energy in this.</td>', 'Good radial energy in this.', '2010-12-12 23:16:58.000000', NULL, 1),
(6252199, 923322, 76335, '<td valign="top">This is astounding. I feel like I can (should) literally dive into it, but I know I''d only hit my head on my monitor.</td>', 'This is astounding. I feel like I can (should) literally dive into it, but I know I''d only hit my head on my monitor.', '2010-12-12 23:17:38.000000', NULL, 1),
